// Hardcoded harmless memory programs only. No USB, OS input, network or script files.
#include "journal_driver.h"
#include <cstdio>
#include <cstring>
#include <memory>
#include <stdexcept>
using stage28k::Driver;using stage28k::State;using stage28k::Fault;
namespace k=ds_keyboard;namespace p=ds_preview;namespace b=ds_bridge;namespace j=stage28k;
static unsigned assertions=0;
static void check(bool ok,const char* expression,unsigned line){++assertions;if(!ok){std::fprintf(stderr,"FAIL line=%u condition=%s\n",line,expression);throw std::runtime_error("assertion line "+std::to_string(line));}}
#define CHECK(x) check(bool(x),#x,__LINE__)
struct Context {
 unsigned pressRetries=0,releaseRetries=0,drainRetries=0,syncRetries=0;
 bool refuseAll=false,reenter=false,cancel=false,disconnect=false,ambiguous=false,fail=false,exception=false;
 k::Phase trigger=k::Phase::None;uint32_t calls=0;
 uint64_t previousR=0;uint64_t previousS=0,previousE=0;k::Report previous{};
 static p::Accept decision(void* ptr,Driver& d,const j::Record& r){
  auto& c=*static_cast<Context*>(ptr);++c.calls;
  if(c.previousR==r.report){CHECK(c.previousS==r.session&&c.previousE==r.intent);CHECK(k::Planner::equal(c.previous,r.snapshot));}
  c.previousR=r.report;c.previousS=r.session;c.previousE=r.intent;c.previous=r.snapshot;
  if(c.reenter){auto count=d.recordCount();auto a=d.attempts();CHECK(!d.begin());CHECK(!d.start());CHECK(!d.hold(0,4));CHECK(!d.release(0,4));CHECK(!d.drain());d.step(0);CHECK(d.recordCount()==count&&d.attempts()==a);}
  if(r.phase==c.trigger){if(c.cancel)d.requestCancel();if(c.disconnect)d.mockDisconnect(c.ambiguous);if(c.exception)throw std::bad_alloc();if(c.fail)return p::Accept::Failed;}
  unsigned n=r.phase==k::Phase::Press?c.pressRetries:r.phase==k::Phase::Release?c.releaseRetries:r.phase==k::Phase::Drain?c.drainRetries:r.phase==k::Phase::Sync?c.syncRetries:0;
  return c.refuseAll||r.attempts<=n?p::Accept::Retry:p::Accept::Accepted;
 }
};
static void tick(Driver& d,uint32_t now){auto before=d.attempts();auto ack=d.acknowledgements();d.step(now);CHECK(d.attempts()-before<=1);CHECK(d.work().reportAttempts+d.work().runtimeTicks<=1);if(d.attempts()!=before)CHECK(d.acknowledgements()==ack);}
static void compile(Driver& d,const char* source){CHECK(d.compileMemory(source,std::strlen(source)));unsigned n=0;while(d.compiler().state()==p::CompileState::Compiling&&n++<p::MaxCompileSteps) d.compileStep();CHECK(n<=p::MaxCompileSteps);CHECK(d.compiler().state()==p::CompileState::Complete);CHECK(d.program().ready());}
static void ready(Driver& d,const char* text,uint32_t now=0){compile(d,text);CHECK(d.begin(now));tick(d,now);CHECK(d.state()==State::Prepared);}
static void pump(Driver& d,uint32_t now=0,unsigned ceiling=1000){unsigned n=0;while(d.state()==State::Running&&n++<ceiling)tick(d,now);CHECK(n<=ceiling);CHECK(d.state()==State::TerminalUndrained);}
static void waitIntent(Driver& d,uint32_t now=0){unsigned n=0;while(d.bridge().intent()!=b::Intent::Waiting&&d.state()==State::Running&&n++<200)tick(d,now);CHECK(d.bridge().intent()==b::Intent::Waiting);}
static void bytes(const j::Record* r,const unsigned char (&expected)[8]){CHECK(r!=nullptr);CHECK(r->receipt==j::Receipt::Accepted);CHECK(!std::memcmp(r->acceptedSnapshot.bytes,expected,8));CHECK(!std::memcmp(r->snapshot.bytes,expected,8));}
constexpr unsigned char Z[8]={},A[8]={0,0,4,0,0,0,0,0},SHIFT[8]={2,0,0,0,0,0,0,0},SA[8]={2,0,4,0,0,0,0,0};
static void drain(Driver& d,uint32_t now=0){CHECK(d.state()==State::TerminalUndrained);CHECK(!d.begin(now));CHECK(d.drain(now));unsigned n=0;while(d.state()==State::DrainPending&&n++<300)tick(d,now);CHECK(n<=300&&d.state()==State::Drained);CHECK(d.drainReport()!=0);CHECK(!d.uncertain());bytes(d.record(d.recordCount()-1),Z);}
static void snapshot(const Driver& d){
 std::printf(",\"state\":%u,\"fault\":%u,\"attempts\":%u,\"acceptances\":%u,\"source_intents\":%zu,\"source_acks\":%u,\"delay_acks\":%u,\"receipts\":[",unsigned(d.state()),unsigned(d.diagnostic().fault),d.attempts(),d.accepted(),d.intentCount(),d.acknowledgements(),d.delayAcknowledgements());
 for(size_t n=0;n<d.recordCount();++n){const auto& r=*d.record(n);std::printf("%s{\"S\":%llu,\"E\":%llu,\"R\":%llu,\"phase\":%u,\"attempts\":%u,\"receipt_state\":%u,\"last_outcome\":%u,\"snapshot\":\"",n?",":"",(unsigned long long)r.session,(unsigned long long)r.intent,(unsigned long long)r.report,unsigned(r.phase),r.attempts,unsigned(r.receipt),unsigned(r.last));for(unsigned char v:r.snapshot.bytes)std::printf("%02X",v);std::printf("\",\"accepted_snapshot\":\"");for(unsigned char v:r.acceptedSnapshot.bytes)std::printf("%02X",v);std::printf("\"}");}
 std::printf("],\"intents\":[");for(size_t n=0;n<d.intentCount();++n){const auto& i=*d.intent(n);std::printf("%s{\"S\":%llu,\"E\":%llu,\"kind\":%u,\"state\":%u,\"admitted_at\":%u,\"ack_at\":%u,\"reports_accepted\":%u,\"acks\":%u}",n?",":"",(unsigned long long)i.session,(unsigned long long)i.intent,unsigned(i.kind),unsigned(i.state),i.admittedAt,i.acknowledgedAt,i.reportsAccepted,i.acknowledgements);}std::printf("]");
}
